mapper.select:
SELECT
b.client_name, c.pet_name, c.pet_photo, c.pet_variety, c.pet_status, c.pet_sex, c.pet_birthday, d.department_name FROM appointment a, client b, pet c, department d WHERE a.is_del = 0 AND a.client_id = b.client_id AND a.pet_id = c.pet_id AND a.department_id = d.department_id AND a.doctor_id = #{doctorId}
AND ((a.is_suc = 0 AND a.miss = 0) OR a.appointment_date >= DATE_SUB(NOW(), INTERVAL 90 DAY)) order by a.is_suc, a.miss, appointment_date desc LIMIT 300
